mapper.select:
select lf.*, s.name as studentName, s.student_no as studentNo, s.avatar as studentAvatar
from lost_found lf
left join student s on lf.student_id = s.id


        and type = #{type}


        and status = #{status}


        and category = #{category}


        and title like concat('%', #{title}, '%')


        and student_id = #{studentId}


order by create_time desc

